let active='全部';const search=document.querySelector('#search'),grid=document.querySelector('#courses');
function render(){const term=search.value.trim().toLowerCase(),items=window.CATALOG.filter(c=>(active==='全部'||c.category===active)&&[c.title,c.category,c.chapter,c.description,...c.steps].join(' ').toLowerCase().includes(term));grid.replaceChildren(...items.map(c=>{const a=document.createElement('a');a.className='card';a.href=c.path;a.innerHTML=`<div class="cover"><img src="${c.cover}" alt="${c.title}科学示意图" width="1200" height="800" loading="lazy"><span class="cover-category">${c.category}</span><span class="cover-number">${String(window.CATALOG.indexOf(c)+1).padStart(2,'0')}</span><span class="play-icon" aria-hidden="true">▶</span></div><div class="card-copy"><div class="chapter">${c.chapter}</div><h3>${c.title}</h3><p>${c.description}</p><div class="card-bottom"><span>${c.id==='trial-story'?'5 幕故事 · 15 项互动任务':c.steps.length+' 步探索 · 旋转动画'}</span><b>开始学习 ↗</b></div></div>`;return a}));document.querySelector('.empty').hidden=items.length>0;document.querySelector('#results').textContent=`显示 ${items.length} 个教学资源`}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()}));search.addEventListener('input',render);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}});render();

